<script setup>
import {ref,watch,onMounted,onUnmounted} from 'vue'
import {api} from '../lib/api'
import {ticketKinds,ticketKindMap} from '../data/ticketKinds'
const search=ref(''),students=ref([]),studentId=ref(''),kind=ref('partner-change'),quantity=ref(1),message=ref(''),history=ref(null),busy=ref(false),loading=ref(false),error=ref(''),notice=ref(''),dialog=ref(null);let alive=true,lookup=0,requestKey=crypto.randomUUID()
async function find(){const seq=++lookup;try{const r=await api('/admin/message-recipients?'+new URLSearchParams({search:search.value}));if(alive&&seq===lookup)students.value=r.items}catch(e){if(alive)error.value=e.message}}
async function load(){const id=studentId.value;history.value=null;if(!id)return;loading.value=true;try{const r=await api('/admin/students/'+id+'/gifts');if(alive&&studentId.value===id)history.value=r}catch(e){if(alive)error.value=e.message}finally{if(alive&&studentId.value===id)loading.value=false}}
watch(studentId,load);watch([studentId,kind,quantity,message],()=>{if(!busy.value){requestKey=crypto.randomUUID();notice.value=''}},{flush:'sync'})
async function send(){if(busy.value||!history.value)return;busy.value=true;error.value='';try{const r=await api('/admin/students/'+studentId.value+'/gifts',{method:'POST',body:{kind:kind.value,quantity:quantity.value,message:message.value,requestKey}});history.value=r;notice.value=r.duplicate?'이미 보낸 선물입니다. 추가로 발송하지 않았어요.':r.student.name+' 학생에게 '+ticketKindMap[kind.value].name+' '+quantity.value+'장을 보냈어요.';requestKey=crypto.randomUUID();dialog.value.close()}catch(e){error.value=e.message}finally{busy.value=false}}
onMounted(find);onUnmounted(()=>{alive=false;lookup++;dialog.value?.close()})
</script>
<template><section class="panel admin-ticket-gifts"><h2>🎁 학생에게 사용권 선물</h2><p>학생이 선물함에서 수령하면 ‘마이 리틀 펫 → 내 아이템 → 사용권’에 저장됩니다.</p><p v-if="notice" role="status" class="notice">{{notice}}</p><p v-if="error" role="alert" class="notice">{{error}}</p><form @submit.prevent="dialog.showModal()"><fieldset :disabled="busy"><div class="gift-form-grid"><label>학생 이름·아이디 검색<input v-model="search" placeholder="학생 검색" maxlength="100" @input="find"/></label><label>선물 받을 학생<select v-model="studentId" required><option disabled value="">학생 선택</option><option v-for="u in students" :key="u.id" :value="u.id">{{u.name}} · {{u.login}} · {{u.class_name}}</option></select></label><label>선물 종류<select v-model="kind"><option v-for="t in ticketKinds" :key="t.id" :value="t.id">{{t.name}}</option></select></label><label>수량<input v-model.number="quantity" type="number" min="1" max="99" step="1" required/></label></div><label>선물 메시지 (선택)<input v-model="message" maxlength="200" placeholder="예: 수업 참여 선물이에요!"/></label><button :disabled="busy||loading||!history||!Number.isInteger(quantity)||quantity<1||quantity>99">선물 보내기</button></fieldset></form><details v-if="history"><summary>보낸 선물 내역 · 최근 {{history.gifts.length}}건</summary><p v-if="!history.gifts.length">아직 보낸 선물이 없어요.</p><article v-for="g in history.gifts" :key="g.id"><strong>{{ticketKindMap[g.kind]?.name}} {{g.quantity}}장</strong><span>{{g.claimed_at?'수령 완료 · 남은 '+g.remaining+'장':'수령 대기'}}</span><small>{{g.sender}} · {{new Date(g.created_at).toLocaleString('ko-KR',{timeZone:'Asia/Seoul'})}}</small><p v-if="g.message">{{g.message}}</p></article></details><dialog ref="dialog" class="ticket-dialog" aria-label="사용권 선물 확인" @cancel.prevent="!busy&&dialog.close()"><h2>선물을 보낼까요?</h2><p>{{history?.student.name}} · @{{history?.student.login}}</p><p>{{ticketKindMap[kind].name}} {{quantity}}장</p><p>{{message}}</p><p v-if="error" role="alert">{{error}}</p><div class="toolbar"><button :disabled="busy" @click="send">{{busy?'보내는 중…':'선물 발송 확정'}}</button><button class="light" :disabled="busy" @click="dialog.close()">취소</button></div></dialog></section></template>
<style scoped>
.admin-ticket-gifts{margin-top:18px}.gift-form-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}.admin-ticket-gifts fieldset{border:0;padding:0;min-width:0}.admin-ticket-gifts label{display:flex;flex-direction:column;gap:8px;margin-bottom:14px;font-size:12px}.admin-ticket-gifts input,.admin-ticket-gifts select{box-sizing:border-box;width:100%;min-width:0}.admin-ticket-gifts article{display:flex;flex-wrap:wrap;gap:10px;padding:14px 0;border-top:1px solid var(--rpg-mid)}.admin-ticket-gifts article small,.admin-ticket-gifts article p{flex-basis:100%;margin:0}.admin-ticket-gifts details{margin-top:20px}@media(max-width:600px){.gift-form-grid{grid-template-columns:1fr}.admin-ticket-gifts input,.admin-ticket-gifts select{font-size:16px}}
</style>
